describe('401 Error Handling - Redirect to Login', () => {
  const loginUrl = '/login';
  const protectedUrl = '/dashboard';
  const apiEndpoint = '/api/user/profile';

  beforeEach(() => {
    cy.visit(protectedUrl);
  });

  it('should redirect to login when API returns 401 Unauthorized', () => {
    cy.intercept('GET', apiEndpoint, {
      statusCode: 401,
      body: { error: 'Unauthorized' }
    }).as('unauthorizedRequest');

    cy.visit(protectedUrl);
    cy.wait('@unauthorizedRequest');

    cy.url().should('include', loginUrl);
    cy.get('h1').should('contain', 'Login');
  });

  it('should handle 401 error during page navigation and show login form', () => {
    cy.intercept('GET', apiEndpoint, {
      statusCode: 401,
      body: { error: 'Token expired' }
    }).as('expiredTokenRequest');

    cy.visit(protectedUrl);
    cy.wait('@expiredTokenRequest');

    cy.url().should('equal', `${Cypress.config().baseUrl}${loginUrl}`);
    cy.get('input[type="email"]').should('be.visible');
    cy.get('input[type="password"]').should('be.visible');
    cy.get('button[type="submit"]').should('contain', 'Sign In');
  });

  it('should preserve redirect destination after successful login following 401', () => {
    cy.intercept('GET', apiEndpoint, {
      statusCode: 401,
      body: { error: 'Unauthorized' }
    }).as('unauthorizedRequest');

    cy.intercept('POST', '/api/auth/login', {
      statusCode: 200,
      body: { token: 'valid-token', user: { id: 1, email: 'user@test.com' } }
    }).as('loginRequest');

    cy.visit(protectedUrl);
    cy.wait('@unauthorizedRequest');

    cy.get('input[type="email"]').type('user@test.com');
    cy.get('input[type="password"]').type('password123');
    cy.get('button[type="submit"]').click();

    cy.wait('@loginRequest');
    cy.url().should('include', protectedUrl);
  });

  it('should handle multiple 401 errors in sequence', () => {
    let requestCount = 0;

    cy.intercept('GET', apiEndpoint, (req) => {
      requestCount++;
      req.reply({
        statusCode: 401,
        body: { error: 'Unauthorized' }
      });
    }).as('unauthorizedRequests');

    cy.visit(protectedUrl);
    cy.wait('@unauthorizedRequests');

    cy.url().should('include', loginUrl);
    cy.visit(protectedUrl);
    cy.wait('@unauthorizedRequests');

    cy.url().should('include', loginUrl);
  });
});
